//! AlgoClerk client: a thin Bevy shell around the engine-agnostic `algoclerk-game` crate.
//!
//! Bevy provides the window, the GPU texture the low-resolution frame is uploaded to, mouse / touch /
//! keyboard input, audio output and the app lifecycle. All game logic lives in `algoclerk-game`.
//!
//! Entry points: `main()` on desktop, `android_main` (generated by `#[bevy_main]`) on Android, and
//! `main_rs` on iOS (called from the Xcode project's `main.m`).
//! The shell structure is adapted from the sibling project Falabichos (Apache-2.0, same owner).

// The only `unsafe` in the workspace: the `#[no_mangle]` entry points that Android and iOS require.
#![cfg_attr(any(target_os = "android", target_os = "ios"), allow(unsafe_code))]

#[cfg(feature = "audio")]
mod audio;
mod cli;
mod controls;
mod display;
mod platform;

use algoclerk_game::layout::choose;
use algoclerk_game::{FileStorage, Game, GameConfig, GameEvent, Input, Key};
use algoclerk_media::Assets as AssetBundle;
use bevy::input::ButtonState;
use bevy::input::keyboard::{Key as LogicalKey, KeyboardInput};
use bevy::input::mouse::{MouseScrollUnit, MouseWheel};
use bevy::input::touch::Touches;
use bevy::prelude::*;
use bevy::render::view::screenshot::{Screenshot, save_to_disk};
use bevy::window::{AppLifecycle, MonitorSelection, PrimaryWindow, WindowMode};
use display::{Frame, SafeInsets};
use std::sync::Arc;

#[derive(Resource)]
struct GameRes(Game);

/// Audio events handed from the game to the (optional) audio system.
#[derive(Resource, Default)]
struct AudioQueue(Vec<GameEvent>);

/// Presses and releases that happen between two fixed ticks are latched here.
#[derive(Resource, Default)]
struct Latch {
    keys: Vec<Key>,
    typed: String,
    pressed: bool,
    released: bool,
    wheel: f32,
    paste: Option<String>,
}

#[derive(Resource)]
struct Opts {
    args: cli::Args,
    smoke_tick: u32,
    shot_taken: bool,
}

#[derive(Resource, Default)]
struct Clip(Option<arboard_shim::Clipboard>);

#[cfg(any(target_os = "windows", target_os = "macos", target_os = "linux"))]
mod arboard_shim {
    pub struct Clipboard(arboard::Clipboard);
    impl Clipboard {
        pub fn new() -> Option<Clipboard> {
            arboard::Clipboard::new().ok().map(Clipboard)
        }
        pub fn set(&mut self, t: &str) {
            let _ = self.0.set_text(t.to_string());
        }
        pub fn get(&mut self) -> Option<String> {
            self.0.get_text().ok()
        }
    }
}

#[cfg(not(any(target_os = "windows", target_os = "macos", target_os = "linux")))]
mod arboard_shim {
    pub struct Clipboard;
    impl Clipboard {
        pub fn new() -> Option<Clipboard> {
            None
        }
        pub fn set(&mut self, _t: &str) {}
        pub fn get(&mut self) -> Option<String> {
            None
        }
    }
}

#[bevy::prelude::bevy_main]
pub fn main() {
    let args = match cli::parse(std::env::args().skip(1)) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {e}\n{}", cli::HELP);
            std::process::exit(2);
        }
    };
    if args.help {
        print!("{}", cli::HELP);
        return;
    }
    if args.version {
        println!("algoclerk {}", algoclerk_game::VERSION);
        return;
    }
    let assets: Arc<AssetBundle> = Arc::new(match &args.assets_dir {
        Some(dir) => AssetBundle::from_dir(dir).unwrap_or_else(|e| {
            eprintln!("cannot read assets from {}: {e}", dir.display());
            std::process::exit(2);
        }),
        None => AssetBundle::embedded(),
    });
    run_window(args, assets);
}

fn run_window(args: cli::Args, #[cfg_attr(not(feature = "audio"), allow(unused_variables))] assets: Arc<AssetBundle>) {
    let mobile = platform::is_mobile();
    let storage = FileStorage::new(platform::data_dir(&args));
    let config = GameConfig { can_quit: !mobile, touch: mobile || args.touch, system_clipboard: !mobile };
    let mut game = match Game::new(&assets, Box::new(storage), config) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("could not start the game: {e}");
            std::process::exit(1);
        }
    };
    let fullscreen = args.fullscreen || game.progress.settings.fullscreen;
    game.progress.settings.fullscreen = fullscreen;
    let window = Window {
        title: "AlgoClerk".into(),
        resolution: (960, 540).into(),
        resizable: true,
        mode: if fullscreen { WindowMode::BorderlessFullscreen(MonitorSelection::Current) } else { WindowMode::Windowed },
        ..default()
    };
    let mut app = App::new();
    app.insert_resource(ClearColor(Color::BLACK))
        .insert_resource(Time::<Fixed>::from_hz(60.0))
        .insert_resource(GameRes(game))
        .insert_resource(AudioQueue::default())
        .insert_resource(Latch::default())
        .insert_resource(Clip(arboard_shim::Clipboard::new()))
        .insert_resource(SafeInsets(platform::safe_insets()))
        .insert_resource(Opts { args, smoke_tick: 0, shot_taken: false })
        .add_plugins(DefaultPlugins.set(WindowPlugin { primary_window: Some(window), ..default() }).set(ImagePlugin::default_nearest()))
        .add_systems(Startup, setup)
        .add_systems(
            Update,
            (collect_input, draw_frame, display::layout_frame, apply_events, lifecycle, autoquit, window_shot, toggle_fullscreen_key).chain(),
        )
        .add_systems(FixedUpdate, tick_game);
    #[cfg(feature = "audio")]
    app.insert_resource(audio::Sound::new(assets.clone())).add_systems(Update, play_audio.after(apply_events));
    app.add_systems(Last, on_exit).run();
}

fn setup(mut commands: Commands, mut images: ResMut<Assets<Image>>) {
    let frame = display::frame_resource(&mut images);
    display::spawn_display(&mut commands, &frame);
    commands.insert_resource(frame);
}

fn collect_input(
    mut kb: MessageReader<KeyboardInput>,
    mut wheel: MessageReader<MouseWheel>,
    mouse: Res<ButtonInput<MouseButton>>,
    touches: Res<Touches>,
    mut latch: ResMut<Latch>,
) {
    for e in kb.read() {
        if e.state != ButtonState::Pressed {
            continue;
        }
        if let Some(k) = controls::map_key(e.key_code) {
            latch.keys.push(k);
        }
        match &e.logical_key {
            LogicalKey::Character(s) => latch.typed.push_str(s.as_str()),
            LogicalKey::Space => latch.typed.push(' '),
            _ => {}
        }
    }
    for w in wheel.read() {
        let notches = match w.unit {
            MouseScrollUnit::Line => w.y,
            MouseScrollUnit::Pixel => w.y / 24.0,
        };
        latch.wheel -= notches;
    }
    if mouse.just_pressed(MouseButton::Left) || touches.iter_just_pressed().next().is_some() {
        latch.pressed = true;
    }
    if mouse.just_released(MouseButton::Left) || touches.iter_just_released().next().is_some() {
        latch.released = true;
    }
}

#[allow(clippy::too_many_arguments)]
fn tick_game(
    keys: Res<ButtonInput<KeyCode>>,
    mouse: Res<ButtonInput<MouseButton>>,
    touches: Res<Touches>,
    windows: Query<&Window, With<PrimaryWindow>>,
    frame: Res<Frame>,
    mut latch: ResMut<Latch>,
    mut game: ResMut<GameRes>,
    mut opts: ResMut<Opts>,
) {
    let l = std::mem::take(&mut *latch);
    let mut input = Input { keys: l.keys, typed: l.typed, wheel: l.wheel, paste: l.paste, ..Input::default() };
    input.ctrl = keys.pressed(KeyCode::ControlLeft) || keys.pressed(KeyCode::ControlRight) || keys.pressed(KeyCode::SuperLeft) || keys.pressed(KeyCode::SuperRight);
    input.shift = keys.pressed(KeyCode::ShiftLeft) || keys.pressed(KeyCode::ShiftRight);
    if let Ok(w) = windows.single() {
        let sf = w.scale_factor();
        let touch_pos = touches.iter().next().map(|t| t.position());
        let (pos, is_touch) = match (touch_pos, w.cursor_position()) {
            (Some(p), _) => (Some(p), true),
            (None, c) => (c, false),
        };
        if let Some(p) = pos {
            input.pointer = Some(frame.display.to_virtual(p.x * sf, p.y * sf));
        }
        input.touch = is_touch;
        input.down = mouse.pressed(MouseButton::Left) || touches.iter().next().is_some();
        input.pressed = l.pressed;
        input.released = l.released;
    }
    if opts.args.smoke {
        opts.smoke_tick += 1;
        smoke(&mut input, opts.smoke_tick);
    }
    game.0.tick(&input);
}

/// Scripted input for the CI boot test: start the campaign, open a level and press play.
fn smoke(input: &mut Input, t: u32) {
    match t {
        30 | 90 | 150 => input.keys.push(Key::Enter),
        220 => input.keys.push(Key::Space),
        _ => {}
    }
}

fn draw_frame(
    mut game: ResMut<GameRes>,
    mut frame: ResMut<Frame>,
    mut images: ResMut<Assets<Image>>,
    windows: Query<&Window, With<PrimaryWindow>>,
    insets: Res<SafeInsets>,
) {
    let Ok(window) = windows.single() else { return };
    let sf = window.scale_factor();
    let (w, h) = (window.width() * sf, window.height() * sf);
    let i = insets.0;
    let touch = game.0.config.touch;
    let d = choose(w, h, (i.0 * sf, i.1 * sf, i.2 * sf, i.3 * sf), touch);
    if d.vp.w != game.0.vp.w || d.vp.h != game.0.vp.h || d.vp.safe != game.0.vp.safe {
        game.0.set_display(&d);
    }
    frame.display = d;
    if frame.drawn_tick == game.0.tick && frame.size == (d.vp.w as usize, d.vp.h as usize) {
        return;
    }
    frame.drawn_tick = game.0.tick;
    let mut canvas = std::mem::replace(&mut frame.canvas, algoclerk_media::Canvas::new(0, 0));
    game.0.draw(&mut canvas);
    if frame.size != (canvas.w, canvas.h) {
        frame.size = (canvas.w, canvas.h);
        let handle = images.add(display::make_image(&canvas));
        frame.handle = handle;
    } else if let Some(mut img) = images.get_mut(&frame.handle) {
        img.data = Some(canvas.px.clone());
    }
    frame.canvas = canvas;
}

#[allow(clippy::too_many_arguments)]
fn apply_events(
    mut game: ResMut<GameRes>,
    mut windows: Query<&mut Window, With<PrimaryWindow>>,
    mut exit: MessageWriter<AppExit>,
    mut clip: ResMut<Clip>,
    mut latch: ResMut<Latch>,
    mut queue: ResMut<AudioQueue>,
    mut sprite: Query<&mut Sprite, With<display::FrameSprite>>,
    frame: Res<Frame>,
) {
    if let Ok(mut s) = sprite.single_mut() {
        if s.image != frame.handle {
            s.image = frame.handle.clone();
        }
    }
    for ev in game.0.take_events() {
        match &ev {
            GameEvent::Quit => {
                exit.write(AppExit::Success);
            }
            GameEvent::Fullscreen(on) => {
                if let Ok(mut w) = windows.single_mut() {
                    w.mode = if *on { WindowMode::BorderlessFullscreen(MonitorSelection::Current) } else { WindowMode::Windowed };
                }
            }
            GameEvent::Copy(t) => {
                if let Some(c) = clip.0.as_mut() {
                    c.set(t);
                }
            }
            GameEvent::PasteRequest => {
                if let Some(c) = clip.0.as_mut() {
                    latch.paste = c.get();
                }
            }
            _ => queue.0.push(ev),
        }
    }
    if !cfg!(feature = "audio") {
        queue.0.clear();
    }
}

#[cfg(feature = "audio")]
fn play_audio(
    mut commands: Commands,
    game: Res<GameRes>,
    mut queue: ResMut<AudioQueue>,
    mut sound: ResMut<audio::Sound>,
    mut sources: ResMut<Assets<bevy::audio::AudioSource>>,
    mut sinks: Query<&mut bevy::audio::AudioSink, With<audio::MusicMarker>>,
) {
    for ev in queue.0.drain(..) {
        match &ev {
            GameEvent::SettingsChanged => sound.apply_volume(&mut sinks, &game.0.progress.settings),
            _ => sound.handle(&ev, &mut commands, &mut sources, &game.0.progress.settings),
        }
    }
}

fn lifecycle(mut events: MessageReader<AppLifecycle>, mut game: ResMut<GameRes>) {
    for e in events.read() {
        if matches!(e, AppLifecycle::WillSuspend | AppLifecycle::Suspended) {
            game.0.on_suspend();
        }
    }
}

fn on_exit(mut exit: MessageReader<AppExit>, mut game: ResMut<GameRes>) {
    if exit.read().next().is_some() {
        game.0.on_suspend();
    }
}

fn window_shot(mut commands: Commands, time: Res<Time>, mut opts: ResMut<Opts>) {
    if opts.shot_taken {
        return;
    }
    if let Some(path) = opts.args.window_shot.clone()
        && time.elapsed_secs() > opts.args.window_shot_after
    {
        opts.shot_taken = true;
        commands.spawn(Screenshot::primary_window()).observe(save_to_disk(path));
    }
}

fn autoquit(time: Res<Time>, opts: Res<Opts>, mut exit: MessageWriter<AppExit>) {
    if let Some(s) = opts.args.autoquit
        && time.elapsed_secs() > s
    {
        exit.write(AppExit::Success);
    }
}

fn toggle_fullscreen_key(keys: Res<ButtonInput<KeyCode>>, mut windows: Query<&mut Window, With<PrimaryWindow>>, mut game: ResMut<GameRes>) {
    let alt = keys.pressed(KeyCode::AltLeft) || keys.pressed(KeyCode::AltRight);
    if (keys.just_pressed(KeyCode::F11) || (alt && keys.just_pressed(KeyCode::Enter)))
        && let Ok(mut w) = windows.single_mut()
    {
        let on = matches!(w.mode, WindowMode::Windowed);
        w.mode = if on { WindowMode::BorderlessFullscreen(MonitorSelection::Current) } else { WindowMode::Windowed };
        game.0.progress.settings.fullscreen = on;
    }
}

/// iOS entry point, called from `ios/AlgoClerk/main.m`.
#[cfg(target_os = "ios")]
#[unsafe(no_mangle)]
pub extern "C" fn main_rs() {
    main();
}
